-- Issue 08: historical zero placeholder and atomic custom-rate bundle.
begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(instance_id,id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
select '00000000-0000-0000-0000-000000000000',('d0310800-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'authenticated','authenticated','issue08-'||n||'@example.test','',now(),'{"provider":"email","providers":["email"]}','{"display_name":"Issue 08"}',now(),now() from generate_series(1,4) n;
create temp table i8(k text primary key, v uuid);
insert into i8 select 'u'||n, p.id from generate_series(1,4) n join public.participants p on p.auth_user_id=('d0310800-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid;
create function pg_temp.id(key text) returns uuid language sql as $$ select v from i8 where k=$1 $$;
create function pg_temp.claim(n int) returns void language plpgsql as $$ begin perform set_config('request.jwt.claims', jsonb_build_object('sub','d0310800-0000-4000-8000-'||lpad(n::text,12,'0'),'role','authenticated','is_anonymous',false)::text, true); end $$;
create function pg_temp.payload(ids uuid[], paid bigint[], shares bigint[], amount bigint, currency text) returns jsonb language sql as $$ select jsonb_build_object('expense_scope','space','target_space_id',pg_temp.id('trip'),'participant_ids',ids,'contribution_amounts',paid,'share_amounts',shares,'total_minor',amount,'currency_code',currency,'description','Issue 08','category','Food','occurred_on','2026-11-03') $$;
grant all on table i8 to authenticated;
set local role authenticated;
select pg_temp.claim(1);
insert into i8 values('trip', public.create_space('trip','Issue 08 Trip',null,null,'MYR'));
reset role;
insert into public.space_members(space_id,participant_id,role) values (pg_temp.id('trip'),pg_temp.id('u2'),'full_access'),(pg_temp.id('trip'),pg_temp.id('u3'),'view'),(pg_temp.id('trip'),pg_temp.id('u4'),'view');
set local role authenticated;
select pg_temp.claim(2);
insert into i8 values('bill', (public.create_trip_expense_editor(gen_random_uuid(), pg_temp.id('trip'), pg_temp.payload(array[pg_temp.id('u2'),pg_temp.id('u3')], array[17200,0], array[8600,8600], 17200, 'MYR'), array[pg_temp.id('u2'),pg_temp.id('u3')])->>'expense_id')::uuid);
select pg_temp.claim(1);
select lives_ok($$select public.remove_space_member(pg_temp.id('trip'), pg_temp.id('u3'))$$, 'owner can remove a member without rewriting bills');
select pg_temp.claim(2);
select lives_ok($$select public.save_trip_expense_editor(gen_random_uuid(), pg_temp.id('bill'), 1, pg_temp.id('trip'), 'shared', false, pg_temp.payload(array[pg_temp.id('u2'),pg_temp.id('u3')], array[17200,0], array[17200,0], 17200, 'MYR'), array[pg_temp.id('u2')])$$, 'removed member can remain as a zero placeholder');
select throws_ok($$select public.save_trip_expense_editor(gen_random_uuid(), (select id from public.expenses where corrects_expense_id=pg_temp.id('bill')), 1, pg_temp.id('trip'), 'shared', false, pg_temp.payload(array[pg_temp.id('u2'),pg_temp.id('u3')], array[17200,0], array[8600,8600], 17200, 'MYR'), array[pg_temp.id('u2'),pg_temp.id('u3')])$$, 'P0001', 'participant_not_in_space', 'a removed member cannot receive a new positive share');
insert into i8 values('myr', (public.create_trip_expense_editor(gen_random_uuid(), pg_temp.id('trip'), pg_temp.payload(array[pg_temp.id('u2'),pg_temp.id('u4')], array[10000,0], array[0,10000], 10000, 'MYR'), array[pg_temp.id('u2'),pg_temp.id('u4')])->>'expense_id')::uuid);
insert into i8 values('vnd', (public.create_trip_expense_editor(gen_random_uuid(), pg_temp.id('trip'), pg_temp.payload(array[pg_temp.id('u4'),pg_temp.id('u2')], array[120000,0], array[0,120000], 120000, 'VND'), array[pg_temp.id('u4'),pg_temp.id('u2')])->>'expense_id')::uuid);
insert into i8 values('account', (public.create_personal_account(gen_random_uuid(),'Issue 08 cash','cash','MYR',null,null,false)->>'account_id')::uuid);
select pg_temp.claim(4);
select throws_ok($$select public.propose_fx_settlement_bundle(gen_random_uuid(), pg_temp.id('trip'), pg_temp.id('u2'), 'MYR', 'custom', '{"VND":"6000"}'::jsonb, 4000, pg_temp.id('account'))$$, 'P0001', 'settlement_cash_account_invalid', 'a debtor cannot pay from someone else''s account');
insert into i8 values('account4', (public.create_personal_account(gen_random_uuid(),'Issue 08 payer','cash','MYR',null,null,false)->>'account_id')::uuid);
insert into i8 values('request', gen_random_uuid());
insert into i8 values('bundle', (public.propose_fx_settlement_bundle(pg_temp.id('request'), pg_temp.id('trip'), pg_temp.id('u2'), 'MYR', 'custom', '{"VND":"6000"}'::jsonb, 4000, pg_temp.id('account4'))->>'bundle_id')::uuid);
select is((public.propose_fx_settlement_bundle(pg_temp.id('request'), pg_temp.id('trip'), pg_temp.id('u2'), 'MYR', 'custom', '{"VND":"6000"}'::jsonb, 4000, pg_temp.id('account4'))->>'bundle_id')::uuid, pg_temp.id('bundle'), 'the same request does not create a second bundle');
select is((select status from public.settlement_fx_bundles where id=pg_temp.id('bundle')), 'pending', 'a proposal does not settle before confirmation');
reset role;
select is(private.space_signed_outstanding(pg_temp.id('trip'), pg_temp.id('u4'), pg_temp.id('u2'), 'MYR'), 10000::bigint, 'pending bundle does not reduce the original balance');
set local role authenticated;
select pg_temp.claim(1);
select throws_ok($$select public.respond_fx_settlement_bundle(pg_temp.id('bundle'), 'accepted', 1)$$, 'P0001', 'settlement_participant_denied', 'a third member cannot confirm the bundle');
select pg_temp.claim(2);
insert into i8 values('account2', (public.create_personal_account(gen_random_uuid(),'Issue 08 receiver','cash','MYR',null,null,false)->>'account_id')::uuid);
select throws_ok($$select public.respond_fx_settlement_bundle(pg_temp.id('bundle'), 'accepted', 1, pg_temp.id('account4'))$$, 'P0001', 'settlement_cash_account_invalid', 'the receiver cannot be paid into the payer account');
select lives_ok($$select public.respond_fx_settlement_bundle(pg_temp.id('bundle'), 'accepted', 1, pg_temp.id('account2'))$$, 'the counterparty accepts the whole bundle');
select is((select status from public.settlement_fx_bundles where id=pg_temp.id('bundle')), 'accepted', 'acceptance is atomic');
reset role;
select is(private.space_signed_outstanding(pg_temp.id('trip'), pg_temp.id('u4'), pg_temp.id('u2'), 'MYR'), 5000::bigint, 'half of the MYR obligation remains');
select is(private.space_signed_outstanding(pg_temp.id('trip'), pg_temp.id('u2'), pg_temp.id('u4'), 'VND'), 60000::bigint, 'half of the VND offset remains');
select is((select count(*) from public.settlement_payments where fx_cash_only and note='fx-cash'), 1::bigint, 'one cash fact is recorded and is excluded from the debt balance above');
select is((select coalesce(sum(entry.amount_minor),0)::bigint from public.personal_account_entries entry join public.personal_account_transactions tx on tx.id=entry.transaction_id where tx.owner_participant_id=pg_temp.id('u4') and tx.kind='settlement_out'), -4000::bigint, 'the payer cash account is reduced once');
select is((select coalesce(sum(entry.amount_minor),0)::bigint from public.personal_account_entries entry join public.personal_account_transactions tx on tx.id=entry.transaction_id where tx.owner_participant_id=pg_temp.id('u2') and tx.kind='settlement_in'), 4000::bigint, 'the receiver cash account is increased once');
select is((select count(*) from public.personal_account_transactions where kind in ('income','expense_funding')), 0::bigint, 'cash settlement is not income or spending');
select pg_temp.claim(4);
select throws_ok($$select public.reverse_settlement_allocation(gen_random_uuid(), (select a.id from public.settlement_allocations a join public.settlement_payments p on p.id=a.settlement_payment_id where p.note='fx-coverage' limit 1), 1, 'split')$$, 'P0001', 'fx_bundle_reversal_required', 'one coverage cannot be reversed alone');
select pg_temp.claim(4);
insert into i8 values('again', gen_random_uuid());
insert into i8 values('second', (public.propose_fx_settlement_bundle(pg_temp.id('again'), pg_temp.id('trip'), pg_temp.id('u2'), 'MYR', 'custom', '{"VND":"6000"}'::jsonb, 2000, pg_temp.id('account4'))->>'bundle_id')::uuid);
select throws_ok($$select public.propose_fx_settlement_bundle(gen_random_uuid(), pg_temp.id('trip'), pg_temp.id('u2'), 'MYR', 'custom', '{"VND":"6000"}'::jsonb, 4000, pg_temp.id('account4'))$$, 'P0001', 'invalid_amount', 'a second request cannot cover the amount already reserved');
select pg_temp.claim(2);
select lives_ok($$select public.respond_fx_settlement_bundle(pg_temp.id('second'), 'declined', 1, null)$$, 'the receiver can decline');
reset role;
select is(private.space_signed_outstanding(pg_temp.id('trip'), pg_temp.id('u4'), pg_temp.id('u2'), 'MYR'), 5000::bigint, 'declining does not change the remaining debt');
select is((select count(*) from public.personal_account_transactions where kind='settlement_out'), 1::bigint, 'declining does not post another cash entry');
set local role authenticated;
select pg_temp.claim(4);
insert into i8 values('later', gen_random_uuid());
insert into i8 values('third', (public.propose_fx_settlement_bundle(pg_temp.id('later'), pg_temp.id('trip'), pg_temp.id('u2'), 'MYR', 'custom', '{"VND":"6000"}'::jsonb, 1000, pg_temp.id('account4'))->>'bundle_id')::uuid);
select lives_ok($$select public.cancel_fx_settlement_bundle(pg_temp.id('third'), 1)$$, 'the payer can cancel a pending bundle');
reset role;
select is(private.space_signed_outstanding(pg_temp.id('trip'), pg_temp.id('u4'), pg_temp.id('u2'), 'MYR'), 5000::bigint, 'cancelling releases the reservation without adding debt');
set local role authenticated;
select pg_temp.claim(2);
select lives_ok($$select public.reverse_fx_settlement_bundle(gen_random_uuid(), pg_temp.id('bundle'), 2)$$, 'either party can reverse the whole bundle');
reset role;
select is(private.space_signed_outstanding(pg_temp.id('trip'), pg_temp.id('u4'), pg_temp.id('u2'), 'MYR'), 10000::bigint, 'reversal restores the MYR debt');
select is(private.space_signed_outstanding(pg_temp.id('trip'), pg_temp.id('u2'), pg_temp.id('u4'), 'VND'), 120000::bigint, 'reversal restores the VND debt');
select is((select coalesce(sum(entry.amount_minor),0)::bigint from public.personal_account_entries entry join public.personal_account_transactions tx on tx.id=entry.transaction_id where tx.owner_participant_id=pg_temp.id('u4') and tx.kind in ('settlement_out','reversal')), 0::bigint, 'payer cash nets back to zero');
select is((select coalesce(sum(entry.amount_minor),0)::bigint from public.personal_account_entries entry join public.personal_account_transactions tx on tx.id=entry.transaction_id where tx.owner_participant_id=pg_temp.id('u2') and tx.kind in ('settlement_in','reversal')), 0::bigint, 'receiver cash nets back to zero');
reset role;
insert into tabby_fx.snapshots(id,rates,fetched_at) values ('d0310800-0000-4000-8000-000000000099', '{"VND":{"currency":"VND","quote":"MYR","numerator":"1","denominator":"6000","provider":"Frankfurter","rateDate":"2026-11-03"}}'::jsonb, now());
update tabby_fx.refresh_state set snapshot_id='d0310800-0000-4000-8000-000000000099', failure=null, succeeded_at=now();
set local role authenticated;
select pg_temp.claim(4);
insert into i8 values('system-request', gen_random_uuid());
select lives_ok($$select public.propose_fx_settlement_bundle(pg_temp.id('system-request'), pg_temp.id('trip'), pg_temp.id('u2'), 'MYR', 'system', '{}'::jsonb, 4000, pg_temp.id('account4'))$$, 'a system snapshot can price the same net');
select is((select quote->'rates'->'VND'->>'provider' from public.settlement_fx_bundles where client_request_id=pg_temp.id('system-request')), 'Frankfurter', 'the system quote keeps the provider');
select is((select quote->'rates'->'VND'->>'rateDate' from public.settlement_fx_bundles where client_request_id=pg_temp.id('system-request')), '2026-11-03', 'the system quote keeps the rate date');
reset role;
update tabby_fx.snapshots set rates='{}'::jsonb where id='d0310800-0000-4000-8000-000000000099';
set local role authenticated;
select pg_temp.claim(4);
select throws_ok($$select public.propose_fx_settlement_bundle(gen_random_uuid(), pg_temp.id('trip'), pg_temp.id('u2'), 'MYR', 'system', '{}'::jsonb, 4000, pg_temp.id('account4'))$$, 'P0001', 'fx_rate_unavailable', 'a missing system rate is rejected');
reset role;
update public.expenses set version=version+1 where id=pg_temp.id('myr');
set local role authenticated;
select pg_temp.claim(4);
select throws_ok($$select public.respond_fx_settlement_bundle((select id from public.settlement_fx_bundles where client_request_id=pg_temp.id('system-request')), 'accepted', 1, pg_temp.id('account2'))$$, 'P0001', 'settlement_participant_denied', 'the payer cannot confirm');
select pg_temp.claim(2);
select throws_ok($$select public.respond_fx_settlement_bundle((select id from public.settlement_fx_bundles where client_request_id=pg_temp.id('system-request')), 'accepted', 1, pg_temp.id('account2'))$$, 'P0001', 'balance_changed', 'a changed source expense blocks confirmation');
reset role;
select is((select count(*) from public.personal_account_transactions where kind='settlement_out'), 1::bigint, 'a rejected confirmation does not post cash');
set local role authenticated;
select pg_temp.claim(1);
insert into i8 values('tiny', public.create_space('trip','Issue 08 Tiny',null,null,'MYR'));
reset role;
insert into public.space_members(space_id,participant_id,role) values (pg_temp.id('tiny'),pg_temp.id('u2'),'full_access'),(pg_temp.id('tiny'),pg_temp.id('u4'),'view');
set local role authenticated;
select pg_temp.claim(2);
insert into i8 values('tiny-bill', (public.create_trip_expense_editor(gen_random_uuid(), pg_temp.id('tiny'), jsonb_build_object('expense_scope','space','target_space_id',pg_temp.id('tiny'),'participant_ids',array[pg_temp.id('u2'),pg_temp.id('u4')],'contribution_amounts',array[1,0],'share_amounts',array[0,1],'total_minor',1,'currency_code','VND','description','Tiny','category','Food','occurred_on','2026-11-03'), array[pg_temp.id('u2'),pg_temp.id('u4')])->>'expense_id')::uuid);
select pg_temp.claim(4);
select throws_ok($$select public.propose_fx_settlement_bundle(gen_random_uuid(), pg_temp.id('tiny'), pg_temp.id('u2'), 'MYR', 'custom', '{"VND":"0.01"}'::jsonb, 1, pg_temp.id('account4'))$$, 'P0001', 'amount_too_small', 'a partial that covers no source minor is rejected');
-- Fresh, isolated closeout pair: no production rows are touched.
reset role;
create function pg_temp.close_payload(c text,payer uuid,consumer uuid,n bigint)returns jsonb language sql as $$select jsonb_build_object('expense_scope','space','target_space_id',pg_temp.id('close-trip'),'participant_ids',array[payer,consumer],'contribution_amounts',array[n,0],'share_amounts',array[0,n],'total_minor',n,'currency_code',c,'description','Closeout source','category','Food','occurred_on','2026-11-04')$$;
set local role authenticated;
select pg_temp.claim(1);
insert into i8 values('close-trip',public.create_space('trip','Closeout pair',null,null,'MYR'));
reset role;
insert into public.space_members(space_id,participant_id,role)values(pg_temp.id('close-trip'),pg_temp.id('u2'),'full_access'),(pg_temp.id('close-trip'),pg_temp.id('u4'),'view');
set local role authenticated;
select pg_temp.claim(2);
insert into i8 values('close-myr',(public.create_trip_expense_editor(gen_random_uuid(),pg_temp.id('close-trip'),pg_temp.close_payload('MYR',pg_temp.id('u2'),pg_temp.id('u4'),10000),array[pg_temp.id('u2'),pg_temp.id('u4')])->>'expense_id')::uuid);
select pg_temp.claim(2);
insert into i8 values('close-vnd',(public.create_trip_expense_editor(gen_random_uuid(),pg_temp.id('close-trip'),pg_temp.close_payload('VND',pg_temp.id('u4'),pg_temp.id('u2'),120000),array[pg_temp.id('u4'),pg_temp.id('u2')])->>'expense_id')::uuid);
select pg_temp.claim(4);
insert into i8 values('close-usd-account',(public.create_personal_account(gen_random_uuid(),'Closeout USD','cash','USD',null,null,false)->>'account_id')::uuid);
select pg_temp.claim(1);
insert into i8 values('close-unrelated',(public.create_trip_expense_editor(gen_random_uuid(),pg_temp.id('close-trip'),pg_temp.close_payload('MYR',pg_temp.id('u1'),pg_temp.id('u2'),500),array[pg_temp.id('u1'),pg_temp.id('u2')])->>'expense_id')::uuid);
reset role;
create function pg_temp.close_versions()returns jsonb language sql as $$select coalesce(jsonb_agg(jsonb_build_object('id',e.id,'version',e.version)order by e.id),'[]'::jsonb)from public.expenses e where e.id in(pg_temp.id('close-myr'),pg_temp.id('close-vnd'))$$;
insert into tabby_fx.snapshots(id,fetched_at,rates)values('d0310800-0000-4000-8100-000000000099',now(),jsonb_build_object('USD',jsonb_build_object('currency','USD','quote','MYR','numerator','4','denominator','1','provider','Test reference','rateDate',current_date::text,'fetchedAt',now(),'direction','MYR-per-foreign'),'VND',jsonb_build_object('currency','VND','quote','MYR','numerator','1','denominator','6000','provider','Test reference','rateDate',current_date::text,'fetchedAt',now(),'direction','MYR-per-foreign')));
update tabby_fx.refresh_state set snapshot_id='d0310800-0000-4000-8100-000000000099',succeeded_at=now(),failure=null where singleton;
select is(private.fx_pair_expense_versions(pg_temp.id('close-trip'),pg_temp.id('u4'),pg_temp.id('u2')),pg_temp.close_versions(),'source snapshot uses actual bilateral obligations, not another pair in MYR');
set local role authenticated;
select pg_temp.claim(4);
insert into i8 values('close-system-request',gen_random_uuid());
insert into i8 values('close-system',(public.propose_fx_settlement_bundle(pg_temp.id('close-system-request'),pg_temp.id('close-trip'),pg_temp.id('u2'),'USD','system','{}'::jsonb,2000,pg_temp.id('close-usd-account'),'d0310800-0000-4000-8100-000000000099',pg_temp.close_versions(),2000,'full')->>'bundle_id')::uuid);
select is((select full_net_minor from public.settlement_fx_bundles where id=pg_temp.id('close-system')),2000::bigint,'MYR and VND rebase correctly into USD');
select is((select (quote->'rates'->'MYR'->>'numerator')::numeric/(quote->'rates'->'MYR'->>'denominator')::numeric from public.settlement_fx_bundles where id=pg_temp.id('close-system')),4::numeric,'system snapshot records 1 USD = 4 MYR');
select is((select jsonb_array_length(quote->'expenses')from public.settlement_fx_bundles where id=pg_temp.id('close-system')),2,'unrelated same-currency bill is not in the quote');
select is((public.propose_fx_settlement_bundle(pg_temp.id('close-system-request'),pg_temp.id('close-trip'),pg_temp.id('u2'),'USD','system','{}'::jsonb,2000,pg_temp.id('close-usd-account'),'d0310800-0000-4000-8100-000000000099',pg_temp.close_versions(),2000,'full')->>'bundle_id')::uuid,pg_temp.id('close-system'),'guarded command reconciles an identical network retry');
select lives_ok($$select public.cancel_fx_settlement_bundle(pg_temp.id('close-system'),1)$$,'cancel still releases the original cash reservation');
select throws_ok($$select public.propose_fx_settlement_bundle(gen_random_uuid(),pg_temp.id('close-trip'),pg_temp.id('u2'),'USD','system','{}'::jsonb,2000,pg_temp.id('close-usd-account'),gen_random_uuid(),pg_temp.close_versions(),2000,'full')$$,'P0001','quote_changed','a replaced system snapshot cannot silently become a different payment');
insert into i8 values('bad-full-request',gen_random_uuid());
select throws_ok($$select public.propose_fx_settlement_bundle(pg_temp.id('bad-full-request'),pg_temp.id('close-trip'),pg_temp.id('u2'),'MYR','custom','{"VND":"6000"}'::jsonb,7000,pg_temp.id('account4'),null,pg_temp.close_versions(),8000,'full')$$,'P0001','quote_changed','Full does not silently become a partial when the quote changes');
select is((select count(*)::int from public.settlement_fx_bundles where client_request_id=pg_temp.id('bad-full-request')),0,'quote mismatch rolls back the whole reservation');
select throws_ok($$select public.propose_fx_settlement_bundle(gen_random_uuid(),pg_temp.id('close-trip'),pg_temp.id('u2'),'MYR','custom','{"VND":"6000"}'::jsonb,8000,pg_temp.id('account4'),null,'[]'::jsonb,8000,'full')$$,'P0001','quote_changed','changed source versions reject atomically');
insert into i8 values('close-accept',(public.propose_fx_settlement_bundle(gen_random_uuid(),pg_temp.id('close-trip'),pg_temp.id('u2'),'MYR','custom','{"VND":"6000"}'::jsonb,8000,pg_temp.id('account4'),null,pg_temp.close_versions(),8000,'full')->>'bundle_id')::uuid);
select pg_temp.claim(2);
select lives_ok($$select public.respond_fx_settlement_bundle(pg_temp.id('close-accept'),'accepted',1,pg_temp.id('account2'))$$,'recipient confirms the guarded cash snapshot');
select pg_temp.claim(1);
select throws_ok($$select public.respond_fx_settlement_bundle(pg_temp.id('close-accept'),'accepted',1,null)$$,'P0001','settlement_participant_denied','a third actor cannot replay an accepted receipt');
select pg_temp.claim(4);
select lives_ok($$select public.reverse_fx_settlement_bundle(gen_random_uuid(),pg_temp.id('close-accept'),2)$$,'whole-bundle reversal remains available');
-- A normal confirmed transfer changes the balance without changing expense versions.
insert into i8 values('close-stale',(public.propose_fx_settlement_bundle(gen_random_uuid(),pg_temp.id('close-trip'),pg_temp.id('u2'),'MYR','custom','{"VND":"6000"}'::jsonb,8000,pg_temp.id('account4'),null,pg_temp.close_versions(),8000,'full')->>'bundle_id')::uuid);
reset role;
insert into i8 values('external-payment',gen_random_uuid());
insert into public.settlement_payments(id,client_request_id,scope,space_id,debtor_participant_id,currency,amount_minor,payment_date,status,cash_tracking_required)values(pg_temp.id('external-payment'),gen_random_uuid(),'space',pg_temp.id('close-trip'),pg_temp.id('u4'),'MYR',1000,current_date,'confirmed',false);
insert into public.settlement_allocations(settlement_payment_id,creditor_participant_id,amount_minor,state)values(pg_temp.id('external-payment'),pg_temp.id('u2'),1000,'accepted');
set local role authenticated;
select pg_temp.claim(2);
select throws_ok($$select public.respond_fx_settlement_bundle(pg_temp.id('close-stale'),'accepted',1,pg_temp.id('account2'))$$,'P0001','balance_changed','confirmation revalidates coverage after a normal transfer');
select is((select status from public.settlement_fx_bundles where id=pg_temp.id('close-stale')),'pending','rejected acceptance does not partially confirm');
select pg_temp.claim(4);
select lives_ok($$select public.cancel_fx_settlement_bundle(pg_temp.id('close-stale'),1)$$,'a stale proposal can still be cancelled');
select throws_ok($$select public.propose_fx_settlement_bundle(gen_random_uuid(),pg_temp.id('tiny'),pg_temp.id('u2'),'MYR','custom','{"VND":"600000000"}'::jsonb,0,null)$$,'P0001','amount_too_small','a rounded-zero one-way debt is not a free offset');
-- Real two-way zero-cash offset: keep coverage, post no zero cash fact.
select pg_temp.claim(1);
insert into i8 values('offset-trip',public.create_space('trip','Closeout offset',null,null,'MYR'));
reset role;
insert into public.space_members(space_id,participant_id,role)values(pg_temp.id('offset-trip'),pg_temp.id('u2'),'full_access'),(pg_temp.id('offset-trip'),pg_temp.id('u4'),'view');
create function pg_temp.offset_payload(c text,payer uuid,consumer uuid,n bigint)returns jsonb language sql as $$select pg_temp.close_payload(c,payer,consumer,n)||jsonb_build_object('target_space_id',pg_temp.id('offset-trip'))$$;
set local role authenticated;
select pg_temp.claim(2);
select public.create_trip_expense_editor(gen_random_uuid(),pg_temp.id('offset-trip'),pg_temp.offset_payload('MYR',pg_temp.id('u2'),pg_temp.id('u4'),10000),array[pg_temp.id('u2'),pg_temp.id('u4')]);
select pg_temp.claim(2);
select public.create_trip_expense_editor(gen_random_uuid(),pg_temp.id('offset-trip'),pg_temp.offset_payload('VND',pg_temp.id('u4'),pg_temp.id('u2'),600000),array[pg_temp.id('u4'),pg_temp.id('u2')]);
select pg_temp.claim(4);
insert into i8 values('offset',(public.propose_fx_settlement_bundle(gen_random_uuid(),pg_temp.id('offset-trip'),pg_temp.id('u2'),'MYR','custom','{"VND":"6000"}'::jsonb,0,null)->>'bundle_id')::uuid);
select pg_temp.claim(2);
select lives_ok($$select public.respond_fx_settlement_bundle(pg_temp.id('offset'),'accepted',1,null)$$,'both directions of a zero-cash offset are confirmed');
select is((select cash_payment_id from public.settlement_fx_bundles where id=pg_temp.id('offset')),null::uuid,'zero offset creates no fake cash payment');
reset role;
select is(private.space_signed_outstanding(pg_temp.id('offset-trip'),pg_temp.id('u4'),pg_temp.id('u2'),'MYR'),0::bigint,'offset fully covers MYR');
select is(private.space_signed_outstanding(pg_temp.id('offset-trip'),pg_temp.id('u2'),pg_temp.id('u4'),'VND'),0::bigint,'offset fully covers VND');

-- Actual VND cash is independent from MYR-equivalent debt and requires a
-- matching owned account, even for a custom-rate partial payment.
set local role authenticated;
select pg_temp.claim(1);
insert into i8 values('cash-trip',public.create_space('trip','Native cash regression',null,null,'MYR'));
reset role;
insert into public.space_members(space_id,participant_id,role)values(pg_temp.id('cash-trip'),pg_temp.id('u2'),'full_access'),(pg_temp.id('cash-trip'),pg_temp.id('u4'),'view');
set local role authenticated;
select pg_temp.claim(2);
select public.create_trip_expense_editor(gen_random_uuid(),pg_temp.id('cash-trip'),pg_temp.close_payload('MYR',pg_temp.id('u2'),pg_temp.id('u4'),20000)||jsonb_build_object('target_space_id',pg_temp.id('cash-trip')),array[pg_temp.id('u2'),pg_temp.id('u4')]);
select public.create_trip_expense_editor(gen_random_uuid(),pg_temp.id('cash-trip'),pg_temp.close_payload('VND',pg_temp.id('u2'),pg_temp.id('u4'),600000)||jsonb_build_object('target_space_id',pg_temp.id('cash-trip')),array[pg_temp.id('u2'),pg_temp.id('u4')]);
select pg_temp.claim(4);
select throws_ok($$select public.propose_fx_settlement_bundle(gen_random_uuid(),pg_temp.id('cash-trip'),pg_temp.id('u2'),'VND','custom','{"MYR":"0.00016"}'::jsonb,500000,null)$$,'P0001','settlement_cash_account_invalid','no account cannot record VND cash');
select throws_ok($$select public.propose_fx_settlement_bundle(gen_random_uuid(),pg_temp.id('cash-trip'),pg_temp.id('u2'),'VND','custom','{"MYR":"0.00016"}'::jsonb,500000,pg_temp.id('account4'))$$,'P0001','settlement_cash_account_invalid','MYR account cannot fund VND cash');
insert into i8 values('vnd-payer',(public.create_personal_account(gen_random_uuid(),'Native VND cash','cash','VND',null,null,false)->>'account_id')::uuid);
select is((select count(*)::int from public.settlement_fx_bundles where space_id=pg_temp.id('cash-trip')),0,'creating an account or failed validation never records a payment');
insert into i8 values('vnd-partial',(public.propose_fx_settlement_bundle(gen_random_uuid(),pg_temp.id('cash-trip'),pg_temp.id('u2'),'VND','custom','{"MYR":"0.00016"}'::jsonb,500000,pg_temp.id('vnd-payer'),null,(select jsonb_agg(jsonb_build_object('id',id,'version',version)order by id)from public.expenses where space_id=pg_temp.id('cash-trip')),1850000,'partial')->>'bundle_id')::uuid);
select is((select cash_minor from public.settlement_fx_bundles where id=pg_temp.id('vnd-partial')),500000::bigint,'VND partial stores 500000 actual VND, not 500000 MYR');
select is((select status from public.settlement_fx_bundles where id=pg_temp.id('vnd-partial')),'pending','a recorded partial still needs recipient confirmation');
select pg_temp.claim(2);
insert into i8 values('vnd-receiver',(public.create_personal_account(gen_random_uuid(),'Receive VND','cash','VND',null,null,false)->>'account_id')::uuid);
select lives_ok($$select public.respond_fx_settlement_bundle(pg_temp.id('vnd-partial'),'accepted',1,pg_temp.id('vnd-receiver'))$$,'recipient confirms VND into their own VND account');
reset role;
select is((select sum(amount_minor)::bigint from public.personal_account_entries where account_id=pg_temp.id('vnd-payer')),-500000::bigint,'payer journal debits exactly 500000 VND');
select is((select sum(amount_minor)::bigint from public.personal_account_entries where account_id=pg_temp.id('vnd-receiver')),500000::bigint,'recipient journal credits exactly 500000 VND');
select is(private.space_signed_outstanding(pg_temp.id('cash-trip'),pg_temp.id('u4'),pg_temp.id('u2'),'MYR'),14595::bigint,'partial coverage reduces original MYR by 5405 minor');
select is(private.space_signed_outstanding(pg_temp.id('cash-trip'),pg_temp.id('u4'),pg_temp.id('u2'),'VND'),437838::bigint,'partial coverage reduces original VND by 162162');

select * from finish();
rollback;
